///
/// \file variableinfo.h
/// \brief Declares the description of a simulated OPC UA variable.
///

#pragma once

#include <QString>
#include <QStringList>
#include <QVariant>

///
/// \brief Waveform or sequence the simulator generates for a variable.
///
enum class SimulationFunction { None, Sine, Square, Triangle, Ramp, Random, Step, Toggle, Counter, List };

///
/// \brief How a variable value is generated by the simulator.
///
struct SimulationSettings
{
    /// \brief Waveform; None leaves the value untouched.
    SimulationFunction function = SimulationFunction::None;
    /// \brief Update interval in milliseconds.
    int intervalMs = 1000;
    /// \brief Length of one waveform cycle in milliseconds.
    int periodMs = 10000;
    /// \brief Peak deviation from the offset.
    double amplitude = 0.0;
    /// \brief Centre value of the generated signal.
    double offset = 0.0;
    /// \brief Values List cycles through, as text of the variable's data type.
    QStringList values;
};

///
/// \brief OPC UA alarm the server raises from a variable's value.
///
struct AlarmSettings
{
    /// \brief Whether the variable has an alarm.
    bool enabled = false;
    /// \brief Whether the HighHigh limit applies to a numeric variable.
    bool highHighEnabled = false;
    /// \brief Value at or above which the HighHigh state is active.
    double highHigh = 0.0;
    /// \brief Whether the High limit applies to a numeric variable.
    bool highEnabled = false;
    /// \brief Value at or above which the High state is active.
    double high = 0.0;
    /// \brief Whether the Low limit applies to a numeric variable.
    bool lowEnabled = false;
    /// \brief Value at or below which the Low state is active.
    double low = 0.0;
    /// \brief Whether the LowLow limit applies to a numeric variable.
    bool lowLowEnabled = false;
    /// \brief Value at or below which the LowLow state is active.
    double lowLow = 0.0;
    /// \brief Value of a Boolean variable that keeps its off-normal alarm inactive.
    bool normalValue = false;
    /// \brief Event severity from 1 (lowest) to 1000.
    int severity = 500;

    ///
    /// \brief Compares every field.
    /// \param other Settings to compare with.
    /// \return True when all fields are equal.
    ///
    bool operator==(const AlarmSettings &other) const
    {
        return enabled == other.enabled && highHighEnabled == other.highHighEnabled && highHigh == other.highHigh
            && highEnabled == other.highEnabled && high == other.high && lowEnabled == other.lowEnabled
            && low == other.low && lowLowEnabled == other.lowLowEnabled && lowLow == other.lowLow
            && normalValue == other.normalValue && severity == other.severity;
    }

    ///
    /// \brief Tells whether any field differs.
    /// \param other Settings to compare with.
    /// \return True when a field differs.
    ///
    bool operator!=(const AlarmSettings &other) const
    {
        return !(*this == other);
    }
};

///
/// \brief OPC UA property of a variable, such as the EURange of an analog item.
///
struct PropertyInfo
{
    /// \brief Browse name, without namespace.
    QString browseName;
    /// \brief Data type name, e.g. "Range", "EUInformation" or "LocalizedText[]" for an array.
    QString dataType;
    /// \brief Value as text, as VariableProperties::toText() writes it; empty while the property has no value.
    QString value;
    /// \brief Whether the value can be typed as text of the data type.
    bool editable = false;
    /// \brief Whether the user changed the value text since it was shown.
    bool edited = false;
};

///
/// \brief Describes one variable of an object in the address space.
///
struct VariableInfo
{
    ///
    /// \brief OPC UA value quality; each value is the StatusCode the server reports (OPC UA Part 8, 7.3).
    ///
    enum class Quality : quint32 {
        Good = 0x00000000,
        GoodLocalOverride = 0x00960000,
        Uncertain = 0x40000000,
        UncertainNoCommunicationLastUsableValue = 0x408F0000,
        UncertainLastUsableValue = 0x40900000,
        UncertainSubstituteValue = 0x40910000,
        UncertainInitialValue = 0x40920000,
        UncertainSensorNotAccurate = 0x40930000,
        UncertainEngineeringUnitsExceeded = 0x40940000,
        UncertainSubNormal = 0x40950000,
        Bad = 0x80000000,
        BadConfigurationError = 0x80890000,
        BadNotConnected = 0x808A0000,
        BadDeviceFailure = 0x808B0000,
        BadSensorFailure = 0x808C0000,
        BadOutOfService = 0x808D0000,
        BadNoCommunication = 0x80310000,
        BadWaitingForInitialData = 0x80320000,
    };

    ///
    /// \brief Lists every quality, grouped by severity.
    /// \return Qualities in display order.
    ///
    static QList<Quality> qualities()
    {
        return { Quality::Good,
                 Quality::GoodLocalOverride,
                 Quality::Uncertain,
                 Quality::UncertainNoCommunicationLastUsableValue,
                 Quality::UncertainLastUsableValue,
                 Quality::UncertainSubstituteValue,
                 Quality::UncertainInitialValue,
                 Quality::UncertainSensorNotAccurate,
                 Quality::UncertainEngineeringUnitsExceeded,
                 Quality::UncertainSubNormal,
                 Quality::Bad,
                 Quality::BadConfigurationError,
                 Quality::BadNotConnected,
                 Quality::BadDeviceFailure,
                 Quality::BadSensorFailure,
                 Quality::BadOutOfService,
                 Quality::BadNoCommunication,
                 Quality::BadWaitingForInitialData };
    }

    ///
    /// \brief Returns the generic quality of a status code's severity.
    /// \param statusCode OPC UA StatusCode.
    /// \return Good, Uncertain or Bad.
    ///
    static Quality severityOf(quint32 statusCode)
    {
        // Bits 30-31 of a StatusCode hold its severity (OPC UA Part 4, 7.39).
        switch (statusCode >> 30) {
        case 0:  return Quality::Good;
        case 1:  return Quality::Uncertain;
        default: return Quality::Bad;
        }
    }

    ///
    /// \brief Returns the quality a status code is reported with.
    /// \param statusCode OPC UA StatusCode; its info bits are ignored.
    /// \return The listed quality of that code, or the generic one of its severity.
    ///
    static Quality qualityOf(quint32 statusCode)
    {
        const auto code = Quality(statusCode & 0xFFFF0000u);
        return qualities().contains(code) ? code : severityOf(statusCode);
    }

    /// \brief String form of the node identifier.
    QString nodeId;
    /// \brief Display name.
    QString displayName;
    /// \brief Resource name of the custom icon; empty selects the variable type's UI icon.
    QString icon;
    /// \brief UI-only icon of the variable type, separate from the saved custom icon.
    QString typeIcon = QStringLiteral("variable-type");
    /// \brief Current value.
    QVariant value;
    /// \brief Built-in data type name; of the elements for an array.
    QString dataType;
    /// \brief Name of a data type a model defines, e.g. an enumeration whose values dataType encodes; empty for
    ///        a built-in type.
    QString dataTypeName;
    /// \brief Number of elements of an array variable; 0 for a scalar.
    int arrayLength = 0;
    /// \brief Access level text: "Read", "Write" or "Read/Write".
    QString access;
    /// \brief Quality of the current value.
    Quality quality = Quality::Good;
    /// \brief Value the variable starts with; text typed by the user until it is parsed.
    QVariant initialValue;
    /// \brief Quality the server reports with every value of the variable.
    Quality configuredQuality = Quality::Good;
    /// \brief Simulation that drives the value.
    SimulationSettings simulation;
    /// \brief Whether the properties cannot be edited, e.g. for a model variable of a data type the simulation lacks.
    bool readOnly = false;
    /// \brief Whether an imported model defines the variable, so its name, data type and array length are fixed.
    bool fromModel = false;
    /// \brief Alarm raised from the value.
    AlarmSettings alarm;
    /// \brief Active alarm state, e.g. "High" or "Active"; empty while the alarm is inactive or absent.
    QString alarmState;
    /// \brief Whether the server records the value history.
    bool historizing = false;
    /// \brief Browse name of the variable type, e.g. "AnalogItemType"; empty while the variable is not built.
    QString typeName;
    /// \brief Properties of the variable, followed by the optional ones its type declares and it lacks.
    QList<PropertyInfo> properties;
    /// \brief Whether the node is a property of a variable, whose value text is the only setting edited.
    bool property = false;

    ///
    /// \brief Returns the data type name to show.
    /// \return The name a model gives the data type, or the built-in type name.
    ///
    QString shownDataType() const { return dataTypeName.isEmpty() ? dataType : dataTypeName; }
};
